<?php require 'config.php';require_login();$u=current_user();$orders=array_filter(read_json('orders.json',[]),fn($o)=>$o['user_id']===$u['id']);$title='طلباتي';require 'header.php';?><h1>📦 طلباتي</h1><table class="table"><tr><th>الطلب</th><th>التاريخ</th><th>الإجمالي</th><th>الحالة</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['id'])?></td><td><?=e($o['created_at'])?></td><td><?=money((float)$o['total'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></table><?php require 'footer.php';?>